create table public.chat_groups(id uuid primary key default gen_random_uuid(),owner uuid not null references public.profiles(id),name text not null check(length(name) between 1 and 80),created_at timestamptz default now());
create table public.chat_group_members(group_id uuid references public.chat_groups(id) on delete cascade,member uuid references public.profiles(id) on delete cascade,primary key(group_id,member));
create table public.chat_group_messages(id uuid primary key default gen_random_uuid(),group_id uuid not null references public.chat_groups(id) on delete cascade,sender uuid not null references public.profiles(id),body text not null check(length(body) between 1 and 2000),created_at timestamptz not null default now());
alter table public.chat_groups enable row level security;
alter table public.chat_group_members enable row level security;
alter table public.chat_group_messages enable row level security;
revoke all on public.chat_groups,public.chat_group_members,public.chat_group_messages from anon,authenticated;
grant select on public.chat_groups,public.chat_group_members,public.chat_group_messages to authenticated;
grant insert(owner,name) on public.chat_groups to authenticated;
grant insert(group_id,member) on public.chat_group_members to authenticated;
grant insert(group_id,sender,body) on public.chat_group_messages to authenticated;
grant delete on public.chat_group_members to authenticated;
create function private.owns_chat_group(g uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.chat_groups where id=g and owner=auth.uid())$$;
create function private.in_chat_group(g uuid) returns boolean language sql stable security definer set search_path='' as $$select private.owns_chat_group(g) or exists(select 1 from public.chat_group_members where group_id=g and member=auth.uid())$$;
revoke all on function private.owns_chat_group(uuid),private.in_chat_group(uuid) from public,anon;
grant execute on function private.owns_chat_group(uuid),private.in_chat_group(uuid) to authenticated;
create policy cg_read on public.chat_groups for select to authenticated using(private.in_chat_group(id));
create policy cg_create on public.chat_groups for insert to authenticated with check(owner=auth.uid());
create policy cgm_read on public.chat_group_members for select to authenticated using(private.in_chat_group(group_id));
create policy cgm_add on public.chat_group_members for insert to authenticated with check(private.owns_chat_group(group_id));
create policy cgm_remove on public.chat_group_members for delete to authenticated using(member=auth.uid() or private.owns_chat_group(group_id));
create policy cgmsg_read on public.chat_group_messages for select to authenticated using(private.in_chat_group(group_id));
create policy cgmsg_send on public.chat_group_messages for insert to authenticated with check(sender=auth.uid() and private.in_chat_group(group_id));
create table public.chat_pins(owner uuid references public.profiles(id) on delete cascade,peer uuid references public.profiles(id) on delete cascade,primary key(owner,peer));
alter table public.chat_pins enable row level security;
revoke all on public.chat_pins from anon,authenticated;
grant select,insert,delete on public.chat_pins to authenticated;
create policy cp_own on public.chat_pins for all to authenticated using(owner=auth.uid()) with check(owner=auth.uid());